WITH valid AS (SELECT *, MONTH(start_date) AS start_date_month, DAYOFWEEK(start_date) AS start_date_dayofweek FROM subscriptions WHERE customer_id IS NOT NULL AND MONTH(start_date) IN (3, 4, 11)) SELECT id, plan, start_date, end_date, monthly_fee, start_date_month, COUNT(start_date_dayofweek) OVER w_hist AS running_count_start_date_dayofweek, MAX(start_date_dayofweek) OVER w_hist AS running_max_start_date_dayofweek, AVG(start_date_dayofweek) OVER w_hist AS running_avg_start_date_dayofweek, ROW_NUMBER() OVER w_grp AS event_seq FROM valid WHERE end_date <= '2024-09-01' WINDOW w_hist AS (PARTITION BY status, plan ORDER BY start_date_dayofweek ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_grp AS (PARTITION BY status ORDER BY start_date_dayofweek DESC, id ASC)
